/* Scratch script to empirically confirm MPT transaction ordering/behavior on testnet.
 * Not part of the shipped module — deleted before final delivery.
 */
import { Client, Wallet, MPTAmount } from 'xrpl'

const ISSUER_SEED = '<TESTNET_SEED_REDACTED>'

async function main() {
  const client = new Client('wss://s.altnet.rippletest.net:51233')
  await client.connect()

  const issuer = Wallet.fromSeed(ISSUER_SEED)
  console.log('issuer address', issuer.address)

  const holder = Wallet.generate()
  console.log('holder address', holder.address)

  // Fund holder from issuer
  const fundTx = await client.autofill({
    TransactionType: 'Payment',
    Account: issuer.address,
    Destination: holder.address,
    Amount: '5000000', // 5 XRP in drops
  })
  const fundSigned = issuer.sign(fundTx)
  const fundResult = await client.submitAndWait(fundSigned.tx_blob)
  console.log('fund result', (fundResult.result.meta as any).TransactionResult)

  // Create MPT issuance with RequireAuth, CanLock, CanClawback
  const createTx = await client.autofill({
    TransactionType: 'MPTokenIssuanceCreate',
    Account: issuer.address,
    AssetScale: 2,
    MaximumAmount: '1000000000',
    Flags: {
      tfMPTRequireAuth: true,
      tfMPTCanLock: true,
      tfMPTCanClawback: true,
      tfMPTCanTransfer: true,
    },
  } as any)
  const createSigned = issuer.sign(createTx)
  const createResult = await client.submitAndWait(createSigned.tx_blob)
  const meta = createResult.result.meta as any
  console.log('create result', meta.TransactionResult, meta.mpt_issuance_id)
  const issuanceId = meta.mpt_issuance_id as string

  // Try issuer-authorizing the holder BEFORE the holder opts in
  const preAuthTx = await client.autofill({
    TransactionType: 'MPTokenAuthorize',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Holder: holder.address,
  } as any)
  const preAuthSigned = issuer.sign(preAuthTx)
  const preAuthResult = await client.submitAndWait(preAuthSigned.tx_blob)
  console.log('issuer pre-authorize (before holder opt-in) result', (preAuthResult.result.meta as any).TransactionResult)

  // Now holder opts in
  const optInTx = await client.autofill({
    TransactionType: 'MPTokenAuthorize',
    Account: holder.address,
    MPTokenIssuanceID: issuanceId,
  } as any)
  const optInSigned = holder.sign(optInTx)
  const optInResult = await client.submitAndWait(optInSigned.tx_blob)
  console.log('holder opt-in result', (optInResult.result.meta as any).TransactionResult)

  // Now issuer authorizes (after opt-in)
  const authTx = await client.autofill({
    TransactionType: 'MPTokenAuthorize',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Holder: holder.address,
  } as any)
  const authSigned = issuer.sign(authTx)
  const authResult = await client.submitAndWait(authSigned.tx_blob)
  console.log('issuer authorize (after opt-in) result', (authResult.result.meta as any).TransactionResult)

  // Send payment issuer -> holder
  const payAmount: MPTAmount = { mpt_issuance_id: issuanceId, value: '100' }
  const payTx = await client.autofill({
    TransactionType: 'Payment',
    Account: issuer.address,
    Destination: holder.address,
    Amount: payAmount as any,
  } as any)
  const paySigned = issuer.sign(payTx)
  const payResult = await client.submitAndWait(paySigned.tx_blob)
  console.log('payment result', (payResult.result.meta as any).TransactionResult)

  // Check holder's MPToken object
  const objs = await client.request({
    command: 'account_objects',
    account: holder.address,
    type: 'mptoken',
  } as any)
  console.log('holder mptoken objects', JSON.stringify(objs.result.account_objects, null, 2))

  await client.disconnect()
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

