/* Scratch script part 2: freeze, clawback, ban, global freeze semantics. */
import { Client, Wallet, MPTAmount } from 'xrpl'

const ISSUER_SEED = '<TESTNET_SEED_REDACTED>'

async function submit(client: Client, wallet: Wallet, txJson: any) {
  const prepared = await client.autofill(txJson)
  const signed = wallet.sign(prepared)
  const result = await client.submitAndWait(signed.tx_blob)
  const meta = result.result.meta as any
  return { code: meta.TransactionResult as string, meta, result }
}

async function main() {
  const client = new Client('wss://s.altnet.rippletest.net:51233')
  await client.connect()
  const issuer = Wallet.fromSeed(ISSUER_SEED)

  const h1 = Wallet.generate()
  const h2 = Wallet.generate()
  console.log('h1', h1.address)
  console.log('h2', h2.address)

  for (const h of [h1, h2]) {
    const r = await submit(client, issuer, {
      TransactionType: 'Payment',
      Account: issuer.address,
      Destination: h.address,
      Amount: '5000000',
    })
    console.log('fund', h.address, r.code)
  }

  const create = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceCreate',
    Account: issuer.address,
    AssetScale: 0,
    MaximumAmount: '1000000000',
    Flags: {
      tfMPTRequireAuth: true,
      tfMPTCanLock: true,
      tfMPTCanClawback: true,
      tfMPTCanTransfer: true,
    },
  })
  const issuanceId = create.meta.mpt_issuance_id as string
  console.log('issuance', issuanceId, create.code)

  for (const h of [h1, h2]) {
    const optIn = await submit(client, h, {
      TransactionType: 'MPTokenAuthorize',
      Account: h.address,
      MPTokenIssuanceID: issuanceId,
    })
    console.log('optIn', h.address, optIn.code)
    const auth = await submit(client, issuer, {
      TransactionType: 'MPTokenAuthorize',
      Account: issuer.address,
      MPTokenIssuanceID: issuanceId,
      Holder: h.address,
    })
    console.log('issuerAuth', h.address, auth.code)
    const pay = await submit(client, issuer, {
      TransactionType: 'Payment',
      Account: issuer.address,
      Destination: h.address,
      Amount: { mpt_issuance_id: issuanceId, value: '1000' } as MPTAmount,
    })
    console.log('pay 1000 to', h.address, pay.code)
  }

  // Freeze h1 (per-holder)
  const lockH1 = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceSet',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Holder: h1.address,
    Flags: { tfMPTLock: true },
  })
  console.log('lock h1', lockH1.code)

  // h1 tries to send to h2 while frozen -> expect failure
  const h1ToH2WhileFrozen = await submit(client, h1, {
    TransactionType: 'Payment',
    Account: h1.address,
    Destination: h2.address,
    Amount: { mpt_issuance_id: issuanceId, value: '10' } as MPTAmount,
  })
  console.log('h1->h2 while h1 frozen', h1ToH2WhileFrozen.code)

  // issuer tries to send to h1 while frozen -> ?
  const issuerToH1WhileFrozen = await submit(client, issuer, {
    TransactionType: 'Payment',
    Account: issuer.address,
    Destination: h1.address,
    Amount: { mpt_issuance_id: issuanceId, value: '10' } as MPTAmount,
  })
  console.log('issuer->h1 while h1 frozen', issuerToH1WhileFrozen.code)

  // h1 tries to send back to issuer while frozen -> ?
  const h1ToIssuerWhileFrozen = await submit(client, h1, {
    TransactionType: 'Payment',
    Account: h1.address,
    Destination: issuer.address,
    Amount: { mpt_issuance_id: issuanceId, value: '10' } as MPTAmount,
  })
  console.log('h1->issuer while h1 frozen', h1ToIssuerWhileFrozen.code)

  // Unlock h1
  const unlockH1 = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceSet',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Holder: h1.address,
    Flags: { tfMPTUnlock: true },
  })
  console.log('unlock h1', unlockH1.code)

  // Clawback 300 from h2 (h2 has 1000-10=990 after successful sends? Let's check current balance first)
  const h2ObjsBefore = await client.request({ command: 'account_objects', account: h2.address, type: 'mptoken' } as any)
  console.log('h2 objs before clawback', JSON.stringify(h2ObjsBefore.result.account_objects))

  const clawback = await submit(client, issuer, {
    TransactionType: 'Clawback',
    Account: issuer.address,
    Holder: h2.address,
    Amount: { mpt_issuance_id: issuanceId, value: '300' } as MPTAmount,
  })
  console.log('clawback 300 from h2', clawback.code)

  const h2ObjsAfter = await client.request({ command: 'account_objects', account: h2.address, type: 'mptoken' } as any)
  console.log('h2 objs after clawback', JSON.stringify(h2ObjsAfter.result.account_objects))

  // Ban h2: clawback remaining balance to zero, then revoke authorization
  const remaining = (h2ObjsAfter.result.account_objects[0] as any).MPTAmount
  console.log('h2 remaining balance', remaining)
  const clawRest = await submit(client, issuer, {
    TransactionType: 'Clawback',
    Account: issuer.address,
    Holder: h2.address,
    Amount: { mpt_issuance_id: issuanceId, value: remaining } as MPTAmount,
  })
  console.log('clawback rest from h2', clawRest.code)

  const revoke = await submit(client, issuer, {
    TransactionType: 'MPTokenAuthorize',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Holder: h2.address,
    Flags: { tfMPTUnauthorize: true },
  })
  console.log('issuer revoke auth on h2', revoke.code, revoke.meta.TransactionResult)

  const h2ObjsAfterBan = await client.request({ command: 'account_objects', account: h2.address, type: 'mptoken' } as any)
  console.log('h2 objs after ban', JSON.stringify(h2ObjsAfterBan.result.account_objects))

  // Try to pay banned h2 again
  const payBannedH2 = await submit(client, issuer, {
    TransactionType: 'Payment',
    Account: issuer.address,
    Destination: h2.address,
    Amount: { mpt_issuance_id: issuanceId, value: '5' } as MPTAmount,
  })
  console.log('pay banned h2 again', payBannedH2.code)

  // Global freeze test
  const globalLock = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceSet',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Flags: { tfMPTLock: true },
  })
  console.log('global lock', globalLock.code)

  const payWhileGlobalFrozen = await submit(client, issuer, {
    TransactionType: 'Payment',
    Account: issuer.address,
    Destination: h1.address,
    Amount: { mpt_issuance_id: issuanceId, value: '5' } as MPTAmount,
  })
  console.log('pay h1 while global frozen', payWhileGlobalFrozen.code)

  const globalUnlock = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceSet',
    Account: issuer.address,
    MPTokenIssuanceID: issuanceId,
    Flags: { tfMPTUnlock: true },
  })
  console.log('global unlock', globalUnlock.code)

  const issuanceObj = await client.request({ command: 'ledger_entry', mpt_issuance: issuanceId } as any)
  console.log('issuance flags at end', (issuanceObj.result as any).node.Flags)

  await client.disconnect()
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

