import { Client, Wallet, MPTAmount } from 'xrpl'

const ISSUER_SEED = '<TESTNET_SEED_REDACTED>'

async function submit(client: Client, wallet: Wallet, txJson: any) {
  const prepared = await client.autofill(txJson)
  const signed = wallet.sign(prepared)
  const result = await client.submitAndWait(signed.tx_blob)
  const meta = result.result.meta as any
  return { code: meta.TransactionResult as string, meta }
}

async function main() {
  const client = new Client('wss://s.altnet.rippletest.net:51233')
  await client.connect()
  const issuer = Wallet.fromSeed(ISSUER_SEED)

  const h1 = Wallet.generate()
  const h2 = Wallet.generate()

  for (const h of [h1, h2]) {
    await submit(client, issuer, { TransactionType: 'Payment', Account: issuer.address, Destination: h.address, Amount: '5000000' })
  }

  const create = await submit(client, issuer, {
    TransactionType: 'MPTokenIssuanceCreate',
    Account: issuer.address,
    AssetScale: 0,
    MaximumAmount: '1000000000',
    Flags: { tfMPTRequireAuth: true, tfMPTCanLock: true, tfMPTCanClawback: true, tfMPTCanTransfer: true },
  })
  const issuanceId = create.meta.mpt_issuance_id as string
  console.log('issuance', issuanceId)

  for (const h of [h1, h2]) {
    await submit(client, h, { TransactionType: 'MPTokenAuthorize', Account: h.address, MPTokenIssuanceID: issuanceId })
    await submit(client, issuer, { TransactionType: 'MPTokenAuthorize', Account: issuer.address, MPTokenIssuanceID: issuanceId, Holder: h.address })
    await submit(client, issuer, { TransactionType: 'Payment', Account: issuer.address, Destination: h.address, Amount: { mpt_issuance_id: issuanceId, value: '1000' } as MPTAmount })
  }

  const globalLock = await submit(client, issuer, { TransactionType: 'MPTokenIssuanceSet', Account: issuer.address, MPTokenIssuanceID: issuanceId, Flags: { tfMPTLock: true } })
  console.log('global lock', globalLock.code)

  const h1ToH2 = await submit(client, h1, { TransactionType: 'Payment', Account: h1.address, Destination: h2.address, Amount: { mpt_issuance_id: issuanceId, value: '10' } as MPTAmount })
  console.log('h1->h2 while globally locked', h1ToH2.code)

  const h1ToIssuer = await submit(client, h1, { TransactionType: 'Payment', Account: h1.address, Destination: issuer.address, Amount: { mpt_issuance_id: issuanceId, value: '10' } as MPTAmount })
  console.log('h1->issuer while globally locked', h1ToIssuer.code)

